import sys
import os
import re
import optparse
import signal
import logging
import logging.handlers
import time
from logging.handlers import RotatingFileHandler
import pwd
from abc import abstractmethod
try:
    import commands
except ImportError:
    import subprocess as commands
SYS_USER = pwd.getpwuid(os.getuid()).pw_name
VERSION = 1.0
SOURCE_ENV = "source /etc/profile 2>/dev/null && source /home/%s/.bashrc && source /home/%s/gauss_env_file && env" % (
    SYS_USER, SYS_USER)
env_status, env_output = commands.getstatusoutput(SOURCE_ENV)
if env_status != 0:
    sys.exit("[Gauss-error]: init environment error")
for all_env in env_output.splitlines():
    if len(all_env.split("=")) > 1:
        k, v = all_env.split("=", 1)
        os.environ.update({k: v})
class Logger(object):
    """
    The class is used to define log component.
    """
    def __init__(self):
        pass
    @classmethod
    def set_log_handle(cls, log_file):
        """
        Initialization log
        """
        log = logging.getLogger("auto_emergency")
        log.setLevel(logging.INFO)
        cls.set_handler(log, log_file)
        return log
    @classmethod
    def set_handler(cls, log, log_file_path):
        """
        Configuring the log
        """
        rotate_handler = RotatingFileHandler(
                        log_file_path,
                        "a",
                        10 * 1024 * 1024,
                        10)
        log_format = logging.Formatter("[%(asctime)s][%(lineno)d][%(message)s]")
        rotate_handler.setFormatter(SensitiveMaskDecoratedFormatter(log_format))
        log.addHandler(rotate_handler)
class SensitiveMaskDecoratedFormatter(object):
    def __init__(self, formatter):
        self.formatter = formatter
    def format(self, record):
        msg = self.formatter.format(record)
        try:
            masked_msg = self.sensitive_mask(msg)
        except Exception:
            # if exception happens, log original message
            masked_msg = msg
        finally:
            return masked_msg
    @classmethod
    def sensitive_mask(cls, msg):
        return re.sub(r'(\$\w+x?)[ ]*=[^,]*,', r'\1=***,', msg)
class SigTimeoutError(Exception):
    pass
class Utils(object):
    def __init__(self, connector, logger):
        self.connector = connector
        self.logger = logger
    def execute_command(self, cmd, sql_cmd=True, raise_error=False):
        self.logger.info("Start to run cmd: %s" % cmd)
        if sql_cmd:
            status, output = commands.getstatusoutput(self.connector % cmd)
        else:
            status, output = commands.getstatusoutput(cmd)
        if status != 0 and raise_error:
            self.logger.error("Execute command: %s error: %s" % (cmd, str(output)))
            Utils.raise_error("Execute command: %s error: %s" % (cmd, str(output)))
        self.logger.info("cmd output:\n %s " % output)
        return status, output
    @staticmethod
    def raise_error(msg):
        raise Exception("\033[31mERROR: %s\033[0m" % msg)
class BaseStep(Utils):
    """base step"""
    def __init__(self, step_name, connector, logger):
        self._step_name = step_name
        self.connector = connector
        self.logger = logger
        Utils.__init__(self, connector, logger)
    @property
    def step_name(self):
        """step_name"""
        return self._step_name
    def do_prepare(self):
        """ do prepare"""
        self.logger.info("--------------------------------------Start to run step: %s" % self._step_name)
    def do_clean(self):
        """ do clean"""
        self.logger.info("--------------------------------------Finish to run step: %s\n" % self._step_name)
    def do_exception(self, base_exception):
        """do exception"""
        raise Exception(base_exception)
    def run(self, **kwargs):
        """ run """
        self.do_prepare()
        try:
            self.process(**kwargs)
        except SigTimeoutError:
            return
        except BaseException as base_exception:
            self.do_exception(base_exception)
        finally:
            self.do_clean()
    @abstractmethod
    def process(self, **kwargs):
        """process"""
        pass
    @staticmethod
    def parse_context(context):
        for ind, line in enumerate(context.splitlines()):
            if ind > 1:
                if "rows)" in line and "row)" in line:
                    return
                context_name = line.split("|")[0]
                return context_name.strip()
        return
    def signal_handler(self, signum, frame):
        self.logger.info("Execute exceed 20s and will be return in current function.")
        raise SigTimeoutError("Execute exceed 20s and will be return in current function")
class MemoryTotalStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "memory_total_step"
        BaseStep.__init__(self, step_name, connector, logger)
    def process(self, **kwargs):
        self.logger.info("********************** 获取数据库当前使用内存整体情况 **********************")
        sql = "select * from pv_total_memory_detail limit 100;"
        self.execute_command(sql)
class MemoryTheadStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "memory_thread_step"
        BaseStep.__init__(self, step_name, connector, logger)
    @staticmethod
    def parse_id(context):
        for ind, line in enumerate(context.splitlines()):
            if ind > 1:
                if "rows)" in line and "row)" in line:
                    return
                try:
                    if len(line.split("|")) > 1:
                        first_id = line.split("|")[0].split(".")[1]
                        return first_id.strip()
                except:
                    continue
        return
    def process(self, **kwargs):
        """process"""
        signal.signal(signal.SIGALRM, self.signal_handler)
        signal.alarm(20)
        self.logger.info("********************** 获取线程级别top 20内存上下文 **********************")
        context_sql = "select contextname, sum(totalsize)/1024/1024 totalsize, sum(freesize)/1024/1024 freesize, count(1) sum from pv_thread_memory_context group by contextname order by totalsize desc limit 20;"
        status, output = self.execute_command(context_sql)
        context_name = self.parse_context(output)
        if not context_name:
            return
        signal.alarm(20)
        self.logger.info("********************** 获取线程级别上下文top 1的占用最多的线程ID **********************")
        tid_sql = "select * from pv_thread_memory_detail() where contextname='%s' order by totalsize desc limit 20;" % context_name
        status, output = self.execute_command(tid_sql)
        tid = self.parse_id(output)
        if not tid:
            return
        self.logger.info("********************** 获取线程ID占用最多top 1上下文详情 **********************")
        detail_sql = "select * from gs_get_thread_memctx_detail('%s', '%s') order by size desc limit 100;" % (tid, context_name)
        self.execute_command(detail_sql)
class MemorySharedStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "memory_shared_step"
        BaseStep.__init__(self, step_name, connector, logger)
    def process(self, **kwargs):
        signal.signal(signal.SIGALRM, self.signal_handler)
        signal.alarm(20)
        self.logger.info("********************** 获取共享内存top 20内存上下文**********************")
        context_sql = "select contextname, sum(totalsize)/1024/1024 totalsize, sum(freesize)/1024/1024 freesize, count(1) sum from pg_shared_memory_detail group by contextname order by totalsize desc limit 20;"
        status, output = self.execute_command(context_sql)
        context_name = self.parse_context(output)
        if not context_name:
            return
        self.logger.info("********************** 获取占用共享内存最多的上下文详情 **********************")
        detail_sql = "select * from gs_get_shared_memctx_detail('%s')" % context_name
        self.execute_command(detail_sql)
class MemorySessionStep(BaseStep):
    def __init__(self, context, service):
        step_name = "memory_session_step"
        BaseStep.__init__(self, step_name, context, service)
    @staticmethod
    def parse_session_list(context):
        id_list = []
        for ind, line in enumerate(context.splitlines()):
            if ind > 1:
                if "rows)" in line and "row)" in line:
                    break
                try:
                    first_id = line.split("|")[0].split(".")[1]
                except Exception:
                    continue
                id_list.append(first_id.strip())
        return id_list
    def process(self, **kwargs):
        """process"""
        signal.signal(signal.SIGALRM, self.signal_handler)
        signal.alarm(20)
        self.logger.info("********************** 获取session级别top 20内存上下文 **********************")
        context_sql = "select contextname, sum(totalsize)/1024/1024 totalsize, sum(freesize)/1024/1024 freesize, count(1) sum from pv_session_memory_context group by contextname order by totalsize desc limit 10;"
        status, output = self.execute_command(context_sql)
        context_name = self.parse_context(output)
        if not context_name:
            return
        self.logger.info("********************** 获取session级别内存最多的上下文详情 **********************")
        detail_sql = "select * from gs_get_session_memctx_detail('%s') order by size desc limit 100;" % context_name
        self.execute_command(detail_sql)
        signal.alarm(20)
        self.logger.info("********************** 获取session级别占用最多上下文的top 20 sessionid **********************")
        session_sql = "select sessid, sum(totalsize)/1024/1024 as totalsize, count(1) as count from pv_session_memory_context group by sessid order by totalsize desc limit 20;"
        status, output = self.execute_command(session_sql)
        id_list = self.parse_session_list(output)
        if not id_list:
            return
        self.logger.info("********************** 获取session级别占用最多上下文的top 20 sessionid正在执行的语句 **********************")
        session_detail = "select pid,sessionid,unique_sql_id,state,usename,client_addr,now()-query_start as elp,substring(query,0,100) from pg_stat_activity where sessionid in (%s);" % ",".join(id_list)
        self.execute_command(session_detail)
class SlotSlowStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "slot_slow_step"
        BaseStep.__init__(self, step_name, connector, logger)
    @staticmethod
    def parse_slot_name(context):
        slot_list = []
        for ind, line in enumerate(context.splitlines()):
            if ind > 1:
                if "rows)" in line and "row)" in line:
                    break
                try:
                    if len(line.split("|")) > 1:
                        slot_name = line.split("|")[0]
                        slot_list.append(slot_name.strip())
                except Exception:
                    continue
        return slot_list
    def process(self, **kwargs):
        self.logger.info("********************** 查看逻辑解码时单条事务在内存中缓存的DML语句数量上限 **********************")
        mem_guc_sql = "show max_changes_in_memory;"
        self.execute_command(mem_guc_sql)
        self.logger.info("********************** 查看当前top 30长事务 **********************")
        long_transaction = "select pid,sessionid,unique_sql_id,state,usename,client_addr,now()-xact_start as elp,substring(query,0,100) from pg_stat_activity where  usename NOT IN ('rdsAdmin', 'rdsMetric', 'rdsBackup', 'rdsRepl', 'dbmind_monitor_agent', 'dbmind_monitor')  and state != 'idle' and pid!=0 order by elp desc limit 30;"
        self.execute_command(long_transaction)
        for i in range(3):
            self.logger.info(
                "********************** 第%s次查看当前所有逻辑解码任务状态 **********************" % str(i + 1))
            all_slots_sql = "select * from gs_get_parallel_decode_status() limit 30;"
            status, output = self.execute_command(all_slots_sql)
            slots = self.parse_slot_name(output)
            if slots:
                self.logger.info(
                    "********************** 第%s次查看所有逻辑复制槽详情 **********************" % str(i + 1))
                for slot in slots:
                    slot_detail_sql = "select * from gs_logical_parallel_decode_status('%s');" % slot
                    self.execute_command(slot_detail_sql)
            self.logger.info("********************** 查看当前xlog位点 **********************")
            current_xid_sql = "select * from  pg_current_xlog_location();"
            self.execute_command(current_xid_sql)
            self.logger.info("--------------------wait 60 second -----------------")
            if i == 2:
                break
            time.sleep(60)
class SlotMemoryStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "slot_memory_step"
        BaseStep.__init__(self, step_name, connector, logger)
    def process(self, **kwargs):
        self.logger.info("********************** 查看逻辑解码内存占用率 **********************")
        percent_sql = "select logical_share_mem,logical_session_mem,process_mem,((logical_share_mem+logical_session_mem)*100/process_mem) as logical_mem_rate from (select sum(totalsize)/1024/1024 as logical_share_mem from pg_shared_memory_detail where contextname in('ParallelReorderBufferByXid','ParallelDecodeDispatcher','ParallelDecodeLog')) a,(select sum(totalsize)/1024/1024 as logical_session_mem from pv_session_memory_detail where contextname in('Read Worker','Replication command context')) b,(select memorymbytes as process_mem from pv_total_memory_detail where memorytype='max_process_memory') where 1=1 limit 100;"
        self.execute_command(percent_sql)
        self.logger.info("********************** 查看占用内存高的逻辑解码任务 **********************")
        detail_memory_sql = "select b.thread_id,b.slot_name,a.logical_session_mem from (select split_part(sessid,'.',2) as sessid,sum(totalsize) as logical_session_mem from pv_session_memory_detail where contextname in('Read Worker','Replication command context') group by 1 order by 2 desc) a,(select thread_id,slot_name from gs_get_parallel_decode_thread_info()) b where a.sessid=b.thread_id order by 3 desc limit 30;"
        self.execute_command(detail_memory_sql)
class WaitEventStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "wait_event_step"
        BaseStep.__init__(self, step_name, connector, logger)
    def process(self, **kwargs):
        self.logger.info("********************** 查看当前top20等待事件 **********************")
        if kwargs["component_name"].lower().startswith("cn"):
            sql2 = "select wait_status,wait_event,count(1) from pgxc_thread_wait_status group by 1,2 order by 3 desc limit 20;"
            sql3 = "select a.coorname, a.pid, a.sessionid, a.datname, a.usename, a.client_addr, a.xact_start, a.query_start, (now() - a.query_start)::text as query_runtime, w.wait_status,w.wait_event,w.locktag,w.lockmode,w.block_sessionid,a.query from pgxc_stat_activity a join pgxc_thread_wait_status w on a.sessionid = w.sessionid where a.pid <> pg_backend_pid() and a.state != 'idle'  and usename !='rdsAdmin' order by query_runtime desc limit 100;"
        else:
            sql2 = "select wait_status,wait_event,count(1) from pg_thread_wait_status group by 1,2 order by 3 desc limit 20;"
            sql3 = "select a.pid, a.sessionid, a.datname, a.usename, a.client_addr, a.xact_start, a.query_start, (now() - a.query_start)::text as query_runtime, w.wait_status,w.wait_event,w.locktag,w.lockmode,w.block_sessionid,a.query from pg_stat_activity a join pg_thread_wait_status w on a.sessionid = w.sessionid where a.pid <> pg_backend_pid() and a.state != 'idle'  and usename !='rdsAdmin' order by query_runtime desc limit 100;"
        self.execute_command(sql2)
        self.logger.info("********************** 查看top100慢sql等待事件 **********************")
        self.execute_command(sql3)
        if kwargs.get("start_time") and kwargs.get("end_time"):
            self.logger.info("********************** 查看指定时间点gs_asp中top50等待事件 **********************")
            sql4 = "select wait_status,event,count(1) from gs_asp where sample_time between to_timestamp(%s/1000) and to_timestamp(%s/1000) group by 1,2 order by 3 desc limit 50;" % (kwargs["start_time"], kwargs["end_time"])
            self.execute_command(sql4)
class CpuUseStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "cpu_use_step"
        BaseStep.__init__(self, step_name, connector, logger)
    def process(self, **kwargs):
        self.logger.info("********************** 当前top20 CPU使用情况 **********************")
        self.execute_command("ps aux | head -1; ps aux | grep -v PID | sort -rn -k +3|head", sql_cmd=False)
        self.logger.info("********************** 当前IO使用情况 **********************")
        self.execute_command("iostat -xm 3 5", sql_cmd=False)
class CurrentSqlStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "current_sql_step"
        BaseStep.__init__(self, step_name, connector, logger)
    def process(self, **kwargs):
        self.logger.info("********************** 查看top20长事务 **********************")
        if kwargs["component_name"].lower().startswith("cn"):
            long_transaction = "SELECT coorname,usename,timestamp_diff('second', COALESCE(xact_start, now()), now()) as runtime,pid, sessionid, unique_sql_id,substr(query,0,100) FROM pgxc_stat_activity WHERE 1 = 1 AND pid <> pg_backend_pid() AND state <> 'idle' AND runtime > 60 AND usename NOT IN ('rdsAdmin', 'rdsMetric', 'rdsBackup', 'rdsRepl', 'dbmind_monitor_agent', 'dbmind_monitor') order by runtime desc limit 20;"
            slow_query = "select pid,sessionid,unique_sql_id,state,usename,client_addr,now()-query_start as elp,substring(query,0,100) from pgxc_stat_activity where usename not in ('rdsAdmin', 'rdsMetric', 'rdsBackup', 'rdsRepl', 'dbmind_monitor_agent', 'dbmind_monitor') and state != 'idle' and pid!=0 order by elp desc limit 20;"
            event_query = "select wait_status,wait_event,count(*) from pgxc_thread_wait_status group by 1,2 order by 3 desc limit 20;"
        else:
            long_transaction = "SELECT usename,timestamp_diff('second', COALESCE(xact_start, now()), now()) as runtime,pid, sessionid, unique_sql_id,substr(query,0,100) FROM pg_stat_activity WHERE 1 = 1 AND pid <> pg_backend_pid() AND state <> 'idle' AND runtime > 60 AND usename NOT IN ('rdsAdmin', 'rdsMetric', 'rdsBackup', 'rdsRepl', 'dbmind_monitor_agent', 'dbmind_monitor') order by runtime desc limit 20;"
            slow_query = "select pid,sessionid,unique_sql_id,state,usename,client_addr,now()-query_start as elp,substring(query,0,100) from pg_stat_activity where usename not in ('rdsAdmin', 'rdsMetric', 'rdsBackup', 'rdsRepl', 'dbmind_monitor_agent', 'dbmind_monitor') and state != 'idle' and pid!=0 order by elp desc limit 20;"
            event_query = "select wait_status,wait_event,count(*) from pg_thread_wait_status group by 1,2 order by 3 desc limit 20;"
        self.execute_command(long_transaction)
        self.logger.info("********************** 查看top20慢sql **********************")
        self.execute_command(slow_query)
        self.logger.info("********************** 查看top20等待事件 **********************")
        self.execute_command(event_query)
        for i in range(3):
            self.logger.info("********************** 第%s次查看top20慢sql堆栈信息 **********************" % str(i + 1))
            stack_query = "select pid,sessionid,unique_sql_id,state,now()-query_start as elp,gs_stack(pid) from pg_stat_activity where usename not in ('rdsAdmin', 'rdsMetric', 'rdsBackup', 'rdsRepl', 'dbmind_monitor_agent', 'dbmind_monitor') and state != 'idle' and pid!=0 order by elp desc limit 20;"
            self.execute_command(stack_query)
        status, database_version = self.execute_command("gaussdb --version", sql_cmd=False)
        if status == 0 and "GaussDB Kernel V500" not in database_version:
            self.logger.info("********************** 查看top20慢sql执行计划 **********************")
            explain_query = "select pid,sessionid,unique_sql_id,state,now()-query_start as elp,gs_get_explain(pid) from pg_stat_activity where usename not in ('rdsAdmin', 'rdsMetric', 'rdsBackup', 'rdsRepl', 'dbmind_monitor_agent', 'dbmind_monitor') and state != 'idle' and pid!=0 order by elp desc limit 20;"
            self.execute_command(explain_query)
class DeadTupleStep(BaseStep):
    def __init__(self, connector, logger):
        step_name = "dead_tuple_step"
        BaseStep.__init__(self, step_name, connector, logger)
    def process(self, **kwargs):
        if "database" in kwargs and kwargs["database"]:
            self.connector = self.connector.replace("postgres", kwargs["database"])
        self.logger.info("********************** 查指定库中top100死行较多表信息 **********************")
        dead_tuple = "select schemaname, relname, n_tup_ins,n_tup_upd,n_tup_del,last_data_changed,n_live_tup,n_dead_tup,last_vacuum,last_autovacuum,last_analyze,last_autoanalyze, (n_dead_tup/(n_live_tup+1)) as dead_rating from pg_stat_user_tables order by n_dead_tup desc, dead_rating desc limit 100;"
        self.execute_command(dead_tuple)
        self.logger.info("********************** 打印当前执行语句所有堆栈 **********************")
        all_stack = "select * from gs_stack();"
        self.execute_command(all_stack)
class GeneralMain(Utils):
    def __init__(self):
        self.parser = None
        self.opt = None
        self.connector = None
        self.logger = None
        self.init_context()
        Utils.__init__(self, self.connector, self.logger)
        self.type_function()
    def init_context(self):
        self.parse_args()
        self.logger = Logger.set_log_handle(self.opt.output_log)
        self.init_connect()
    @staticmethod
    def command_sender_parse():
        parser = optparse.OptionParser(conflict_handler="resolve", version=VERSION)
        parser.disable_interspersed_args()
        parser.epilog = ("Example: python3 auto_emergency.py -d postgres -p 8000 -U username -W password"
                         "-T memory_collector -O '/home/Ruby/log/auto_xxx.txt'")
        parser.add_option("-d", "--database", dest="database", type="string",
                          help="the database name to connect")
        parser.add_option("-U", "--username", dest="username", type="string",
                          help="the username to connect database")
        parser.add_option("-W", "--password", dest="password", type="string",
                          help="the password to connect database")
        parser.add_option("-T", "--type", dest="type", type="choice",
                          choices=["memory_collector", "slot_slow_collector", "slot_memory_collector", "cpu_collector", "wait_event_collector"],
                          help="the collector or diagnose type")
        parser.add_option("-s", "--start-time", dest="start_time", type="string", action="store", default="",
                          help="start time, not must")
        parser.add_option("-e", "--end-time", dest="end_time", type="string", action="store", default="",
                          help="end time, not must")
        parser.add_option("-O", "--output-log", dest="output_log", type="string",
                          help="output result to this file.")
        parser.add_option("-C", "--component-name", dest="component_name", type="string",
                          help="output result to this file.")
        return parser
    def get_database_port(self):
        _, output = self.execute_command("cm_ctl view | grep coordinatePort | cut -d ':' -f 2 | head -n 1",
                                         sql_cmd=False, raise_error=True)
        return int(output)
    def init_connect(self):
        port = self.get_database_port()
        self.connector = "gsql -d postgres -p %s -U %s -W %s " % (port, self.opt.username, self.opt.password)
        if self.opt.component_name.lower().startswith("dn"):
            self.connector += '-t -A -c "%s"'
            status, output = commands.getstatusoutput(self.connector %
                                                      "select node_port from pgxc_node where node_name='%s' limit 1;" %
                                                      self.opt.component_name)
            if status != 0:
                Utils.raise_error("Connection DN Error: %s" % str(output))
            if not output.strip():
                Utils.raise_error("Get %s port failed: %s" % (self.opt.component_name, str(output)))
            self.connector = "gsql -d postgres -p %s -U %s -W %s " % (output.strip(), self.opt.username, self.opt.password)
        self.connector += '-c "%s"'
        status, output = commands.getstatusoutput(self.connector % "select 1;")
        if status != 0:
            Utils.raise_error("Connection Error: %s" % str(output))
        else:
            self.logger.info("Connection successfully.")
    def parse_args(self):
        self.parser = self.command_sender_parse()
        self.opt, _ = self.parser.parse_args()
        if not all([self.opt.username, self.opt.password, self.opt.database, self.opt.output_log, self.opt.type]):
            Utils.raise_error("all argument needed. please check it.")
        if self.opt.start_time:
            self.opt.start_time = int(self.opt.start_time)
        if self.opt.end_time:
            self.opt.end_time = int(self.opt.end_time)
